-- đã chạy
-- Điều kiện: 01..10. Không tạo lại lịch hẹn, nhân viên, thuốc hay kho.
BEGIN;
CREATE TABLE IF NOT EXISTS medical."vaccines" (
    "vaccineID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(200) NOT NULL CHECK (length(trim("name")) > 0),
    "manufacturer" VARCHAR(200),
    "targetDisease" TEXT NOT NULL CHECK (length(trim("targetDisease")) > 0),
    "recommendedIntervalDays" INTEGER CHECK ("recommendedIntervalDays" > 0),
    "isActive" BOOLEAN NOT NULL DEFAULT true
);
CREATE TABLE IF NOT EXISTS medical."vaccinationRecords" (
    "vaccinationID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "petID" BIGINT NOT NULL REFERENCES medical."pets"("petID") ON DELETE RESTRICT,
    "visitID" BIGINT REFERENCES medical."medicalVisits"("visitID") ON DELETE RESTRICT,
    "vaccineID" BIGINT NOT NULL REFERENCES medical."vaccines"("vaccineID") ON DELETE RESTRICT,
    "veterinarianID" BIGINT NOT NULL REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE RESTRICT,
    "vaccinationDate" DATE NOT NULL,
    "dose" VARCHAR(150) NOT NULL CHECK (length(trim("dose")) > 0),
    "lotNumber" VARCHAR(100),
    "nextDueDate" DATE,
    "reaction" TEXT,
    "note" TEXT,
    CONSTRAINT "ckVaccinationNextDate" CHECK ("nextDueDate" IS NULL OR "nextDueDate" > "vaccinationDate")
);
CREATE TABLE IF NOT EXISTS medical."followUps" (
    "followUpID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "visitID" BIGINT NOT NULL REFERENCES medical."medicalVisits"("visitID") ON DELETE RESTRICT,
    "petID" BIGINT NOT NULL REFERENCES medical."pets"("petID") ON DELETE RESTRICT,
    "veterinarianID" BIGINT REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE RESTRICT,
    "scheduledDate" DATE NOT NULL,
    "reason" TEXT NOT NULL CHECK (length(trim("reason")) > 0),
    "note" TEXT,
    "status" VARCHAR(20) NOT NULL DEFAULT 'UPCOMING'
        CHECK ("status" IN ('UPCOMING', 'COMPLETED', 'CANCELLED', 'OVERDUE')),
    "appointmentID" BIGINT REFERENCES booking."appointments"("appointmentID") ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS "idxVaccinationRecordsPetDate" ON medical."vaccinationRecords" ("petID", "vaccinationDate" DESC);
CREATE INDEX IF NOT EXISTS "idxVaccinationRecordsVisit" ON medical."vaccinationRecords" ("visitID");
CREATE INDEX IF NOT EXISTS "idxVaccinationRecordsVaccine" ON medical."vaccinationRecords" ("vaccineID");
CREATE INDEX IF NOT EXISTS "idxVaccinationRecordsVet" ON medical."vaccinationRecords" ("veterinarianID");
CREATE INDEX IF NOT EXISTS "idxFollowUpsPetDate" ON medical."followUps" ("petID", "scheduledDate");
CREATE INDEX IF NOT EXISTS "idxFollowUpsVisit" ON medical."followUps" ("visitID");
CREATE INDEX IF NOT EXISTS "idxFollowUpsVet" ON medical."followUps" ("veterinarianID");
CREATE INDEX IF NOT EXISTS "idxFollowUpsAppointment" ON medical."followUps" ("appointmentID");
CREATE INDEX IF NOT EXISTS "idxFollowUpsStatusDate" ON medical."followUps" ("status", "scheduledDate");
COMMENT ON TABLE medical."followUps" IS
    'Đề nghị tái khám, không tự giữ giờ. Appointment chỉ được liên kết sau khi tạo qua booking chung.';
-- Backend: kiểm tra petID khớp visit/appointment, ngày hợp lệ theo nghiệp vụ,
-- vaccine active và bác sĩ có quyền. Không suy ra COMPLETED chỉ từ ngày hẹn.
COMMIT;
